"use strict";(self.webpackChunkdocsite=self.webpackChunkdocsite||[]).push([[8130],{7735:e=>{e.exports=JSON.parse('{"archive":{"blogPosts":[{"id":"welcome","metadata":{"permalink":"/blog/welcome","editUrl":"https://github.com/LDubya/OpenKeyNav_Dev/tree/main/blog/2024-08-13-welcome.md","source":"@site/blog/2024-08-13-welcome.md","title":"Welcome","description":"OpenKeyNav gives developers an open-source JavaScript toolkit for adding an optional keyboard interaction layer to websites and web applications.","date":"2024-08-13T00:00:00.000Z","tags":[{"inline":false,"label":"Basics","permalink":"/blog/tags/basics","description":"Introductions and practical OpenKeyNav fundamentals"}],"readingTime":1.315,"hasTruncateMarker":false,"authors":[{"name":"The OpenKeyNav Team"}],"frontMatter":{"slug":"welcome","title":"Welcome","authors":{"name":"The OpenKeyNav Team"},"tags":["basics"]},"unlisted":false},"content":"OpenKeyNav gives developers an open-source JavaScript toolkit for adding an optional keyboard interaction layer to websites and web applications.\\n\\n## Why OpenKeyNav?\\n\\nPeople who cannot or do not use a mouse need keyboard access. This group includes people who use alternative input devices through a keyboard interface. Developers often make dense interfaces and drag-and-drop interactions depend on a pointer.\\n\\nOpenKeyNav adds keyboard paths for those interactions. Developers must also provide semantic HTML, native controls, established keyboard conventions, and accessibility testing.\\n\\n### Key Features of OpenKeyNav\\n\\n- **On-demand target labels:** OpenKeyNav can display short labels that provide a direct route to detected controls in dense interfaces.\\n- **Complex interactions:** Configured keyboard drag-and-drop and movement modes can provide an alternative to pointer-only operation.\\n- **Customizable activation keys:** Developers can adapt the mode keys to their application and test for browser, operating-system, and assistive-technology conflicts.\\n- **Development diagnostics:** OpenKeyNav debug labels flag likely mouse-only targets for manual investigation. Developers must verify every result.\\n- **Optional interaction layer:** Users can enable or disable the shortcuts and keep using conventional keyboard behavior.\\n\\n## Getting Started\\n\\nStart with one interaction. Preserve its conventional keyboard behavior and evaluate the complete task before expanding the integration.\\n\\nFollow the [Getting Started Guide](https://openkeynav.com/docs/getting_started/quick_start_guide) to install and initialize OpenKeyNav.\\n\\n## Comprehensive Documentation\\n\\nDevelopers can find setup instructions, examples, configuration options, limitations, and testing guidance in the [OpenKeyNav documentation](https://openkeynav.com/docs/intro).\\n\\n## Looking Ahead\\n\\nMaintainers use implementation work, research, and adopter feedback to improve OpenKeyNav interactions, documentation, and test coverage.\\n\\n## Feedback\\n\\nDevelopers can report implementation problems and documentation gaps through the OpenKeyNav project.\\n\\n**The OpenKeyNav Team**"}]}}')}}]);